    // Реактивний об'єкт для форми
    const form = reactive({
      title: '',
      primaryPollId: '',
      formItems: [{
        field_name: '',
        field_type: 'text'
      }]
    });

    // Правила валідації
    const rules = {
      form: {
        title: {
          required
        },
        formItems: {
          // Валідація кожного елемента форми
          $each: {
            field_name: {
